mod positional_case;
test 'case' {
    stack i32 x = 6;
    heap []i32 s = make.{x, -x, ~x, x + 2, x - 2, x * 2, x / 2, x % 4, x & 3, x | 1, x ^ 3, x << 1, x >> 1, x +% 1, x -% 1, x *% 2, x +! 1, x -! 1, x *! 2, (i32)3.0, (i32)sizeof.(i16)};
    expect_eq.(s[0], 6);
    expect_eq.(s[1], -6);
    expect_eq.(s[2], -7);
    expect_eq.(s[3], 8);
    expect_eq.(s[4], 4);
    expect_eq.(s[5], 12);
    expect_eq.(s[6], 3);
    expect_eq.(s[7], 2);
    expect_eq.(s[8], 2);
    expect_eq.(s[9], 7);
    expect_eq.(s[10], 5);
    expect_eq.(s[11], 12);
    expect_eq.(s[12], 3);
    expect_eq.(s[13], 7);
    expect_eq.(s[14], 5);
    expect_eq.(s[15], 12);
    expect_eq.(s[16], 7);
    expect_eq.(s[17], 5);
    expect_eq.(s[18], 12);
    expect_eq.(s[19], 3);
    expect_eq.(s[20], 2);
    rem.(s);
}

mod positional_case;
test 'case' {
    stack i32 x = 6;
    heap []bool s = make.{x == 6, x != 6, x < 7, x > 7, x <= 6, x >= 6, !false};
    expect_eq.(s[0], true);
    expect_eq.(s[1], false);
    expect_eq.(s[2], true);
    expect_eq.(s[3], false);
    expect_eq.(s[4], true);
    expect_eq.(s[5], true);
    expect_eq.(s[6], true);
    rem.(s);
}

mod positional_order;
stack i32 trace = 0;
fn step(stack i32 tag, stack i32 value): i32 {
    trace = trace * 10 + tag;
    ret value;
}
fn work(void): i32 {
    heap []i32 s = make.{step(1, 4), step(2, 5), step(3, 6)};
    defer { rem.(s); }
    ret s[0] + s[1] + s[2];
}
test 'case' { expect_eq.(work(), 15); expect_eq.(trace, 123); }

mod positional_helper;
stack i32 trace = 0;
fn step(stack i32 tag): i32 {
    heap u8 *rw p = new.(7);
    expect.(p != nil);
    trace = trace * 10 + tag;
    rem.(p);
    ret tag;
}
fn work(void): i32 {
    heap []i32 s = make.{step(1), step(2)};
    defer { rem.(s); }
    ret s[0] + s[1];
}
test 'case' { expect_eq.(work(), 3); expect_eq.(trace, 12); }

mod positional_plain_multiline;
fn work(void): i32 {
    heap []i32 s = make.{
        4,
        5,
        6
    };
    defer { rem.(s); }
    ret s[0] + s[1] + s[2];
}
test 'case' { expect_eq.(work(), 15); }

mod positional_conditional;
stack i32 trace = 0;
fn step(stack i32 tag): i32 { trace = trace * 10 + tag; ret tag; }
fn work(void): i32 {
    heap []i32 s = make.{
        true ?
            step(1) :
            step(9),
        false ?
            step(8) :
            step(2)
    };
    defer { rem.(s); }
    ret s[0] + s[1];
}
test 'case' { expect_eq.(work(), 3); expect_eq.(trace, 12); }

mod positional_short;
stack i32 trace = 0;
fn mark(stack i32 tag): bool { trace = trace * 10 + tag; ret true; }
fn work(void): bool {
    heap []bool s = make.{
        false &&
            mark(9),
        true ||
            mark(8),
        true &&
            mark(1),
        false ||
            mark(2)
    };
    defer { rem.(s); }
    ret !s[0] && s[1] && s[2] && s[3];
}
test 'case' { expect.(work()); expect_eq.(trace, 12); }

mod positional_shadow;
stack i32 s = 7;
fn work(void): void {
    { heap []i32 s = make.{s}; defer { rem.(s); } expect_eq.(s[0], 7); }
    stack i16 value = 9;
    { heap []i16 value = make.{value}; defer { rem.(value); } expect_eq.(value[0], 9); }
    { heap []i32 s = make.{3}; defer { rem.(s); } { heap []i16 s = make.{5}; defer { rem.(s); } expect_eq.(s[0], 5); } expect_eq.(s[0], 3); }
}
test 'case' { work(); }

