mod observation_positional_slices;
fn make_sum(void): i32 {
    heap []i32 s = make.{4, 5, 6};
    defer { rem.(s); }
    s[1] = s[1] + 1;
    ret s[0] + s[1] + s[2];
}
fn cold(void): i32 {
    heap []u8 s = make.{9, 10};
    ret len.(s);
}
test 'positional slice coverage' { expect_eq.(make_sum(), 16); }

mod observation_positional_retained;
fn retain(void): i32 {
    heap []i16 s = make.{2, 3, 4};
    ret s[0] + s[1] + s[2];
}
test 'positional retained' { expect_eq.(retain(), 9); }

mod positional_root;
imp util.leaf;
fn work(void): i32 { heap []i32 s = make.{leaf.item()}; defer { rem.(s); } ret s[0]; }
test 'root' { expect_eq.(work(), 9); }

mod util.leaf;
ext fn item(void): i32 { ret 9; }
fn cold(void): i32 { heap []u8 s = make.{1}; ret s[0]; }
test 'leaf' { heap []i16 s = make.{4}; expect_eq.(s[0], 4); rem.(s); }

